import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_upper_triangular_matmul(
    torch::Tensor A,
    torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_upper_triangular_matmul_detail {

constexpr int TILE = 32;
constexpr int THREAD_TILE = 16;
__global__ void cute_upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int local_row = ty * 2;
    const int local_col = tx * 2;
    const int row0 = blockIdx.y * TILE + local_row;
    const int row1 = row0 + 1;
    const int col0 = blockIdx.x * TILE + local_col;
    const int col1 = col0 + 1;
    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(N, N),
        make_stride(N, Int<1>{}));
    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(N, N),
        make_stride(N, Int<1>{}));
    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(N, N),
        make_stride(N, Int<1>{}));
    auto sA = make_tensor(
        make_smem_ptr(&As[0][0]),
        make_shape(Int<TILE>{}, Int<TILE>{}),
        make_stride(Int<TILE>{}, Int<1>{}));
    auto sB = make_tensor(
        make_smem_ptr(&Bs[0][0]),
        make_shape(Int<TILE>{}, Int<TILE>{}),
        make_stride(Int<TILE>{}, Int<1>{}));
    float acc00 = 0.0f;
    float acc01 = 0.0f;
    float acc10 = 0.0f;
    float acc11 = 0.0f;
    for (int k0 = 0; k0 < N; k0 += TILE) {
        const int a_col0 = k0 + local_col;
        const int a_col1 = a_col0 + 1;
        const int b_row0 = k0 + local_row;
        const int b_row1 = b_row0 + 1;
        sA(local_row, local_col) =
            (row0 < N && a_col0 < N) ? gA(row0, a_col0) : 0.0f;
        sA(local_row, local_col + 1) =
            (row0 < N && a_col1 < N) ? gA(row0, a_col1) : 0.0f;
        sA(local_row + 1, local_col) =
            (row1 < N && a_col0 < N) ? gA(row1, a_col0) : 0.0f;
        sA(local_row + 1, local_col + 1) =
            (row1 < N && a_col1 < N) ? gA(row1, a_col1) : 0.0f;
        sB(local_row, local_col) =
            (b_row0 < N && col0 < N) ? gB(b_row0, col0) : 0.0f;
        sB(local_row, local_col + 1) =
            (b_row0 < N && col1 < N) ? gB(b_row0, col1) : 0.0f;
        sB(local_row + 1, local_col) =
            (b_row1 < N && col0 < N) ? gB(b_row1, col0) : 0.0f;
        sB(local_row + 1, local_col + 1) =
            (b_row1 < N && col1 < N) ? gB(b_row1, col1) : 0.0f;
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < TILE; ++kk) {
            const int global_k = k0 + kk;
            if (global_k < N) {
                if (row0 < N && col0 < N && row0 <= col0 &&
                    global_k >= row0 && global_k <= col0) {
                    acc00 += sA(local_row, kk) * sB(kk, local_col);
                }
                if (row0 < N && col1 < N && row0 <= col1 &&
                    global_k >= row0 && global_k <= col1) {
                    acc01 += sA(local_row, kk) * sB(kk, local_col + 1);
                }
                if (row1 < N && col0 < N && row1 <= col0 &&
                    global_k >= row1 && global_k <= col0) {
                    acc10 += sA(local_row + 1, kk) * sB(kk, local_col);
                }
                if (row1 < N && col1 < N && row1 <= col1 &&
                    global_k >= row1 && global_k <= col1) {
                    acc11 += sA(local_row + 1, kk) * sB(kk, local_col + 1);
                }
            }
        }
        __syncthreads();
    }
    if (row0 < N && col0 < N) {
        gC(row0, col0) = (row0 <= col0) ? acc00 : 0.0f;
    }
    if (row0 < N && col1 < N) {
        gC(row0, col1) = (row0 <= col1) ? acc01 : 0.0f;
    }
    if (row1 < N && col0 < N) {
        gC(row1, col0) = (row1 <= col0) ? acc10 : 0.0f;
    }
    if (row1 < N && col1 < N) {
        gC(row1, col1) = (row1 <= col1) ? acc11 : 0.0f;
    }
}

} // namespace cute_upper_triangular_matmul_detail

torch::Tensor cute_upper_triangular_matmul(
    torch::Tensor A,
    torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must have dtype float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must have dtype float32");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(1) == B.size(0), "A and B dimensions must match");

    const int N = static_cast<int>(A.size(0));

    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();
    auto C = torch::empty_like(A_contiguous);

    dim3 block(
        cute_upper_triangular_matmul_detail::THREAD_TILE,
        cute_upper_triangular_matmul_detail::THREAD_TILE);
    dim3 grid(
        (N + cute_upper_triangular_matmul_detail::TILE - 1) /
            cute_upper_triangular_matmul_detail::TILE,
        (N + cute_upper_triangular_matmul_detail::TILE - 1) /
            cute_upper_triangular_matmul_detail::TILE);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_upper_triangular_matmul_detail::cute_upper_triangular_matmul_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        C.data_ptr<float>(),
        N);
    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CuTE upper-triangular matmul kernel launch failed");

    return C;
}
"""

cute_ext = load_inline(
    name="cute_upper_triangular_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_upper_triangular_matmul"],
    extra_cflags=[
        "-O3",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_upper_triangular_matmul(A, B)

